 useEffect(()=>{if(section!=='manufacturing-work-centers'||!calendarCenterId)return;let active=true;const centerId=calendarCenterId,selectionGeneration=calendarSelectionGeneration.current;const isCurrent=()=>active&&activeSection.current==='manufacturing-work-centers'&&centerId===selectedCalendarCenterId.current&&selectionGeneration===calendarSelectionGeneration.current;setSetupRulesReady(false);void request<SetupRule[]>(`/api/manufacturing/work-centers/${centerId}/setup-rules`).then(data=>{if(isCurrent()){setSetupRules(data);setupRulesReadyGeneration.current=selectionGeneration;setSetupRulesReady(true)}}).catch(e=>{if(isCurrent())setError((e as Error).message)});return()=>{active=false}},[request,section,calendarCenterId])
