async function saveBom(e:FormEvent){e.preventDefault();const captured=captureMutationEpoch(),editing=boms.find(x=>x.id===editingBomId);if(editingBomId&&!editing)return;setBusy(true);setError('');setNotice('');const payload={code,name,productStockItemId:product,outputQuantity:Number(output),lines:components.map(x=>({componentStockItemId:x.stockItemId,quantity:Number(x.quantity),scrapPercent:Number(x.scrap),standardUnitCostBase:Number(x.standardUnitCostBase)})),operations:bomOperations.map((x,i)=>({sequence:i+1,workCenterId:x.workCenterId,setupMinutes:Number(x.setupMinutes),runMinutesPerOutputUnit:Number(x.runMinutesPerOutputUnit),minimumWaitDaysAfterPrevious:Number(x.minimumWaitDaysAfterPrevious),setupFamilyCode:x.setupFamilyCode,plannedEnergyKwhPerOutput:Number(x.plannedEnergyKwhPerOutput),plannedEnergyCostPerKwhBase:Number(x.plannedEnergyCostPerKwhBase),eligibleWorkCenterIds:[...new Set([x.workCenterId,...x.alternateWorkCenterIds])]}))};try{await request(editing?`/api/manufacturing/boms/${editing.id}`:'/api/manufacturing/boms/',{method:editing?'PUT':'POST',body:JSON.stringify(editing?{...payload,rowVersion:editing.rowVersion}:payload)});if(!mutationIsCurrent(captured))return;resetBomForm();setNotice(editing?'Ürün reçetesi güncellendi.':'Ürün reçetesi oluşturuldu.');await refresh();onNavigate('manufacturing-recipes')}catch(e){if(mutationIsCurrent(captured))setError((e as Error).message)}finally{if(mutationIsCurrent(captured))setBusy(false)}}
