async function deleteBom(bom:Bom){if(bom.orderCount>0||!window.confirm(`${bom.code} · ${bom.name} reçetesini kalıcı olarak silmek istiyor musunuz? Bu işlem geri alınamaz.`))return;const captured=captureMutationEpoch();setBusy(true);setError('');setNotice('');try{await request(`/api/manufacturing/boms/${bom.id}`,{method:'DELETE'});if(!mutationIsCurrent(captured))return;if(editingBomId===bom.id)resetBomForm();setNotice(`${bom.code} reçetesi silindi.`);await refresh()}catch(e){if(mutationIsCurrent(captured))setError((e as Error).message)}finally{if(mutationIsCurrent(captured))setBusy(false)}}
 async function createWorkCenter(e:FormEvent){e.preventDefault();const captured=captureMutationEpoch();setBusy(true);setError('');setNotice('');try{await request('/api/manufacturing/work-centers/',{method:'POST',body:JSON.stringify({code:wcCode,name:wcName,capacityMinutesPerDay:Number(wcCapacity),laborCostPerHourBase:Number(wcLabor),overheadCostPerHourBase:Number(wcOverhead)})});if(!mutationIsCurrent(captured))return;setWcCode('');setWcName('');setNotice('İş merkezi oluşturuldu.');await refresh()}catch(e){if(mutationIsCurrent(captured))setError((e as Error).message)}finally{if(mutationIsCurrent(captured))setBusy(false)}}
 function changeCalendarCenter(centerId:string){if(centerId===calendarCenterId)return;selectedCalendarCenterId.current=centerId;calendarSelectionGeneration.current++;calendarReadyGeneration.current=-1;setupRulesReadyGeneration.current=-1;workCenterSaveGeneration.current++;if(workCenterSettingsSavePending.current){workCenterSettingsSavePending.current=false;setBusy(false)}setCalendarCenterId(centerId)}
 async function saveWorkCenterCalendar(){const selectionGeneration=calendarSelectionGeneration.current;if(!calendarCenterId||!calendarReady||calendarReadyGeneration.current!==selectionGeneration)return;const captured=captureMutationEpoch(),centerId=calendarCenterId,requestGeneration=++workCenterSaveGeneration.current;const isCurrent=()=>mutationIsCurrent(captured)&&requestGeneration===workCenterSaveGeneration.current&&selectionGeneration===calendarSelectionGeneration.current&&centerId===calendarCenterId;workCenterSettingsSavePending.current=true;setBusy(true);setError('');setNotice('');try{const saved=await request<WorkCenterCalendar>(`/api/manufacturing/work-centers/${centerId}/calendar`,{method:'PUT',body:JSON.stringify({workingDaysMask:calendarMask,shiftStartMinuteOfDay:timeMinute(calendarShiftStart),shiftEndMinuteOfDay:timeMinute(calendarShiftEnd),capacityOverrides:calendarOverrides,annualCapacityRules,shiftRotations})});if(!isCurrent())return;setCalendarMask(saved.workingDaysMask);setCalendarShiftStart(minuteTime(saved.shiftStartMinuteOfDay));setCalendarShiftEnd(minuteTime(saved.shiftEndMinuteOfDay));setCalendarOverrides(saved.capacityOverrides);setAnnualCapacityRules(saved.annualCapacityRules??[]);setShiftRotations(saved.shiftRotations??[]);setNotice('İş merkezi vardiyası ve çalışma takvimi kaydedildi.')}catch(e){if(isCurrent())setError((e as Error).message)}finally{if(isCurrent()){workCenterSettingsSavePending.current=false;setBusy(false)}}}
 async function saveSetupRules(){const selectionGeneration=calendarSelectionGeneration.current;if(!calendarCenterId||!setupRulesReady||setupRulesReadyGeneration.current!==selectionGeneration)return;const captured=captureMutationEpoch(),centerId=calendarCenterId,requestGeneration=++workCenterSaveGeneration.current;const isCurrent=()=>mutationIsCurrent(captured)&&requestGeneration===workCenterSaveGeneration.current&&selectionGeneration===calendarSelectionGeneration.current&&centerId===calendarCenterId;workCenterSettingsSavePending.current=true;setBusy(true);setError('');setNotice('');try{const saved=await request<SetupRule[]>(`/api/manufacturing/work-centers/${centerId}/setup-rules`,{method:'PUT',body:JSON.stringify({rules:setupRules})});if(!isCurrent())return;setSetupRules(saved);setNotice('Sıralı kurulum kuralları kaydedildi. Yeni üretim emirleri bu kural anlık görüntüsünü kullanır.')}catch(e){if(isCurrent())setError((e as Error).message)}finally{if(isCurrent()){workCenterSettingsSavePending.current=false;setBusy(false)}}}
 function addCapacityOverride(e:FormEvent){e.preventDefault();if(!calendarReady||!calendarDate)return;setCalendarOverrides(rows=>[...rows.filter(x=>x.workDate!==calendarDate),{workDate:calendarDate,capacityMinutes:Number(calendarCapacity),note:calendarNote.trim()||null}].sort((a,b)=>a.workDate.localeCompare(b.workDate)));setCalendarDate('');setCalendarCapacity('0');setCalendarNote('')}
 function addAnnualCapacityRule(e:FormEvent){e.preventDefault();if(!calendarReady)return;const month=Number(annualMonth),day=Number(annualDay),probe=new Date(Date.UTC(2000,month-1,day));if(probe.getUTCMonth()+1!==month||probe.getUTCDate()!==day){setError('Yıllık kapasite kuralı için geçerli bir ay ve gün girin.');return}setError('');setAnnualCapacityRules(rows=>[...rows.filter(x=>x.month!==month||x.day!==day),{month,day,capacityMinutes:Number(annualCapacity),note:annualNote.trim()||null}].sort((a,b)=>a.month-b.month||a.day-b.day));setAnnualCapacity('0');setAnnualNote('')}
 function addShiftRotation(e:FormEvent){e.preventDefault();if(!calendarReady)return;const length=Number(rotationLength),start=timeMinute(rotationStart),end=timeMinute(rotationEnd);if(!rotationFrom||length<1||length>366||end<=start){setError('Döngü 1–366 gün olmalı; başlangıç tarihi ve geçerli vardiya saatleri girin.');return}if(rotationTo&&rotationTo<rotationFrom){setError('Bitiş tarihi başlangıç tarihinden önce olamaz.');return}const effectiveTo=rotationTo||null;const overlaps=shiftRotations.some(row=>(row.effectiveToDate===null||row.effectiveToDate>=rotationFrom)&&(effectiveTo===null||row.effectiveFromDate<=effectiveTo));if(overlaps){setError('Vardiya planı tarih aralığı mevcut bir planla çakışıyor. Çakışmayan bir aralık seçin.');return}setError('');const days=Array.from({length},(_,dayIndex)=>({dayIndex,capacityMinutes:Number(rotationCapacity),shiftStartMinuteOfDay:start,shiftEndMinuteOfDay:end}));setShiftRotations(rows=>[...rows,{effectiveFromDate:rotationFrom,effectiveToDate:effectiveTo,note:rotationNote.trim()||null,days}].sort((a,b)=>a.effectiveFromDate.localeCompare(b.effectiveFromDate)));setRotationTo('');setRotationNote('')}
 async function createOrder(e:FormEvent){e.preventDefault();const captured=captureMutationEpoch();setBusy(true);setError('');setNotice('');try{await request('/api/manufacturing/orders/',{method:'POST',body:JSON.stringify({code:orderCode,billOfMaterialId:bomId,warehouseId,plannedQuantity:Number(plannedQuantity),plannedDate})});if(!mutationIsCurrent(captured))return;setOrderCode('');setNotice('Üretim emri planlandı.');await refresh()}catch(e){if(mutationIsCurrent(captured))setError((e as Error).message)}finally{if(mutationIsCurrent(captured))setBusy(false)}}
 async function transition(order:Order,action:'release'|'complete'|'cancel',finishedGoodsTracking?:{trackingCode:string;quantity:number;expiryDate:string|null}[]){const captured=captureMutationEpoch();setBusy(true);setError('');setNotice('');try{const result=await request<{costStatus?:string;totalCostBase?:number;baseCurrencyCode?:string}>(`/api/manufacturing/orders/${order.id}/${action}`,{method:'POST',body:JSON.stringify(action==='complete'?{finishedGoodsTracking:finishedGoodsTracking??[]}:{})});if(!mutationIsCurrent(captured))return;setNotice(action==='complete'?`Üretim tamamlandı.${result?.costStatus==='Valued'?` Mamul maliyeti: ${formatBaseAmount(result.totalCostBase??0,result.baseCurrencyCode||'TRY')}.`:' Bileşen maliyetleri eksik; mamul girişi maliyetsiz kaydedildi.'}`:action==='release'?'Üretim emri serbest bırakıldı.':'Üretim emri iptal edildi.');if(action==='complete')setTrackingOrder(null);await refresh()}catch(e){if(mutationIsCurrent(captured))setError((e as Error).message)}finally{if(mutationIsCurrent(captured))setBusy(false)}}
 function completeOrder(order:Order){const mode=boms.find(x=>x.id===order.billOfMaterialId)?.productTrackingMode??'None';if(mode==='None'){void transition(order,'complete',[]);return}setTrackingOrder(order);setFinishedCode('');setFinishedExpiry('');setFinishedSerials('')}
 async function scheduleOrder(order:Order){const captured=captureMutationEpoch();setBusy(true);setError('');setNotice('');try{await request<Order>(`/api/manufacturing/orders/${order.id}/schedule`,{method:'POST',body:'{}'});if(!mutationIsCurrent(captured))return;setNotice(`${order.code} için iş merkezi kapasitesi ayrıldı.`);await refresh()}catch(e){if(mutationIsCurrent(captured))setError((e as Error).message)}finally{if(mutationIsCurrent(captured))setBusy(false)}}
