 function updateActual(operation:OrderOperation,field:'setup'|'run'|'energyKwh'|'energyRate',value:string){setActualTimes(previous=>{const current=previous[operation.id]??{setup:String(operation.setupMinutes),run:String(operation.runMinutes),energyKwh:'0',energyRate:'0'};return {...previous,[operation.id]:{...current,[field]:value}}})}
 function submitFinishedTracking(e:FormEvent){e.preventDefault();if(!trackingOrder)return;const mode=boms.find(x=>x.id===trackingOrder.billOfMaterialId)?.productTrackingMode??'None';if(mode==='Lot'){void transition(trackingOrder,'complete',[{trackingCode:finishedCode.trim(),quantity:trackingOrder.plannedQuantity,expiryDate:finishedExpiry||null}]);return}const serials=finishedSerials.split(/[\n,;]+/).map(x=>x.trim()).filter(Boolean);void transition(trackingOrder,'complete',serials.map(trackingCode=>({trackingCode,quantity:1,expiryDate:null})))}
 async function runMrp(e:FormEvent){e.preventDefault();if(!warehouseId||mrpDemands.length===0)return;const captured=beginMrpRequest();setBusy(true);setError('');setNotice('');try{const plan=await request<MrpPlan>('/api/manufacturing/mrp/plan',{method:'POST',body:JSON.stringify({warehouseId,planDate:mrpPlanDate,demand:mrpDemands.map(x=>({stockItemId:x.stockItemId,quantity:Number(x.quantity),requiredByDate:x.requiredByDate})),includeOpenSalesOrders:true})});if(!mrpRequestIsCurrent(captured))return;setMrpPlan(plan);setMrpSelected(plan.lines.map((x,i)=>x.issue===null&&['Üret','Satın al'].includes(x.recommendation)?i:-1).filter(i=>i>=0));setMrpBomSelections(Object.fromEntries(plan.lines.map((line,i)=>[i,boms.find(b=>b.isActive&&b.productStockItemId===line.stockItemId)?.id??''])));setPurchaseRequestFieldValues({});const history=await request<MrpPlanHistory[]>('/api/manufacturing/mrp/plans');if(!mrpRequestIsCurrent(captured))return;setMrpHistory(history);if(plan.lines.some(x=>x.recommendation==='Satın al')){const fields=await request<PurchaseRequestField[]>('/api/purchasing/requests/custom-fields');if(!mrpRequestIsCurrent(captured))return;setPurchaseRequestFields(fields)}setNotice('Zaman aşamalı malzeme ihtiyaç planı kaydedildi.')}catch(e){if(mrpRequestIsCurrent(captured))setError((e as Error).message)}finally{if(mrpRequestIsCurrent(captured))setBusy(false)}}
 async function openMrpPlan(id:string){const captured=beginMrpRequest();setBusy(true);setError('');try{const plan=await request<MrpPlan>(`/api/manufacturing/mrp/plans/${id}`);if(!mrpRequestIsCurrent(captured))return;setMrpPlan(plan);setMrpSelected(plan.lines.map((x,i)=>x.issue===null&&['Üret','Satın al'].includes(x.recommendation)&&!plan.convertedLineIndexes?.includes(i)?i:-1).filter(i=>i>=0));setMrpBomSelections(Object.fromEntries(plan.lines.map((line,i)=>[i,boms.find(b=>b.isActive&&b.productStockItemId===line.stockItemId)?.id??''])));if(plan.lines.some(x=>x.recommendation==='Satın al')){const fields=await request<PurchaseRequestField[]>('/api/purchasing/requests/custom-fields');if(!mrpRequestIsCurrent(captured))return;setPurchaseRequestFields(fields)}setNotice('Kaydedilmiş MRP planı açıldı.')}catch(e){if(mrpRequestIsCurrent(captured))setError((e as Error).message)}finally{if(mrpRequestIsCurrent(captured))setBusy(false)}}
